import { html } from "../../../html.js";
import { useEffect,useMemo,useReducer,useState } from "/prototype/vendor/preact-hooks.js";
import { conversations,fmtAgo } from "../data.js";
import { transcriptForConversation } from "./transcripts.js";
import Bubbles from "./chat/bubbles.js"; import Document from "./chat/document.js"; import Timeline from "./chat/timeline.js"; import Ops from "./chat/ops.js";
import { Icon,StatusPill,Menu,EmptyState,Tabs,tone } from "../ui/index.js";
const fields=['org','agent','repo','device','kind','status'],labels={org:'Org',agent:'Agent',repo:'Project',device:'Device',kind:'Kind',status:'Status'},blank={facets:{},quick:{},text:''};
const needs=c=>c.gate||c.unread||['error','held','waiting-followup','waiting-approval'].includes(c.status);
export function parse(q){const tokens=[];const text=q.replace(/([\w-]+):("[^"]+"|'[^']+'|[^\s]+)/g,(_,k,v)=>(tokens.push([k,v.replace(/^['"]|['"]$/g,'')]),'')).trim().toLowerCase();return[tokens,text]}
function match(c,s){const[ts,text]=parse(s.text);if(text&&!`${c.title} ${c.repo} ${c.agent} ${c.branch}`.toLowerCase().includes(text))return false;for(const[k,v]of ts){const f=k==='project'?'repo':k;if(k==='needs'&&v==='me'&&!needs(c))return false;if(k==='unread'&&v==='yes'&&!c.unread)return false;if(fields.includes(f)&&!String(c[f]).toLowerCase().includes(v.toLowerCase()))return false}return fields.every(f=>!s.facets[f]?.length||s.facets[f].includes(c[f]))&&(!s.quick.needs||needs(c))&&(!s.quick.running||c.status==='running')&&(!s.quick.unread||c.unread)&&(!s.quick.errors||c.status==='error')}
function reducer(s,a){if(a.t==='text')return{...s,text:a.v};if(a.t==='quick')return{...s,quick:{...s.quick,[a.k]:!s.quick[a.k]}};if(a.t==='facet'){const x=s.facets[a.f]||[];return{...s,facets:{...s.facets,[a.f]:x.includes(a.v)?x.filter(y=>y!==a.v):[...x,a.v]}}};if(a.t==='clear')return blank;return s}
function Row({c,selected,pick}){return html`<button class=${`e-row ${c.id===selected.id?'selected':''}`} onClick=${()=>pick(c)}><i class=${`e-dot ${tone(c.status)}`}></i><span class="e-rowcopy"><b>${c.title}</b><small>${c.agent} · ${fmtAgo(c.lastActivityAt)} · ${c.branch}</small></span>${c.pr&&html`<em>#${c.pr}</em>`}${c.unread>0&&html`<strong>${c.unread}</strong>`}</button>`}
function Thread({c}){const initial=Number(new URLSearchParams(location.search).get('cs'))||1,[style,setStyle]=useState(initial),[mode,setMode]=useState('follow-up'),[latest,setLatest]=useState(false),events=transcriptForConversation(c),Renderer=[Bubbles,Document,Timeline,Ops][style-1];useEffect(()=>setLatest(false),[c.id]);const switchStyle=n=>{setStyle(n);const url=new URL(location);url.searchParams.set('cs',n);history.replaceState({},'',url)};return html`<div class="e-thread"><div class="e-threadbar"><span>Transcript style</span><div class="e-chat-styles" aria-label="Transcript style">${['Chat','Flow','Timeline','Ops'].map((n,i)=>html`<button class=${style===i+1?'on':''} onClick=${()=>switchStyle(i+1)}>${i+1} ${n}</button>`)}</div></div><div class="e-messages" onScroll=${e=>setLatest(e.currentTarget.scrollTop+e.currentTarget.clientHeight<e.currentTarget.scrollHeight-60)}><${Renderer} events=${events}/></div>${latest&&html`<button class="e-jump" onClick=${e=>{const box=e.currentTarget.parentElement.querySelector('.e-messages');box.scrollTop=box.scrollHeight;setLatest(false)}}>↓ Jump to latest</button>`}<footer class="e-composer"><div><button class=${mode==='follow-up'?'on':''} onClick=${()=>setMode('follow-up')}>Follow-up</button><button class=${mode==='steer'?'on':''} onClick=${()=>setMode('steer')}>Steer</button><span>Claude 4.5</span></div><textarea placeholder=${mode==='steer'?'Steer this run…':'Send a follow-up…'}></textarea><button class="e-send"><${Icon} name="send"/></button></footer></div>`}
function Details({c}){const[tab,setTab]=useState('details');return html`<aside class="e-details"><${Tabs} value=${tab} setValue=${setTab} items=${['details','diff']}/>${tab==='diff'?html`<pre class="e-diff">@@ retry policy @@\n<span class="minus">- return delay * 2</span>\n<span class="plus">+ return Math.random() * ceiling</span></pre>`:html`<div class="e-detail-body"><label>WORK ITEM</label><p>${c.title}</p><label>PR / CI</label><p>${c.pr?`#${c.pr} · ${c.ci}`:'No pull request'}</p><label>BUDGET</label><div class="e-meter"><i></i></div><p>$${c.cost} · 42% daily budget</p><label>AGENT STATUS</label><p><${StatusPill} status=${c.paused?'held':'idle'}/></p></div>`}</aside>`}
export default function Conversations({nav}){const[state,dispatch]=useReducer(reducer,blank),[selected,setSelected]=useState(conversations[1]),[menu,setMenu]=useState(null);useEffect(()=>{const close=e=>{if(!e.target.closest('.e-menu,.e-conv-menu'))setMenu(null)};document.addEventListener('click',close);return()=>document.removeEventListener('click',close)},[]);const visible=useMemo(()=>conversations.filter(c=>match(c,state)).sort((a,b)=>b.lastActivityAt-a.lastActivityAt),[state]);return html`<aside class="e-list"><header><button class="e-new" onClick=${()=>nav('new')}><${Icon} name="square-pen"/> New conversation</button><div class="e-search-wrap"><${Icon} name="search"/><input class="e-search" value=${state.text} onInput=${e=>dispatch({t:'text',v:e.target.value})} placeholder="Search or filter…  /"/></div><div class="e-quick">${[['needs','Needs me'],['running','Running'],['unread','Unread'],['errors','Errors']].map(([k,n])=>html`<button class=${state.quick[k]?'on':''} onClick=${()=>dispatch({t:'quick',k})}>${n}</button>`)}</div></header><div class="e-rows" tabIndex="0">${!visible.length?html`<${EmptyState}>No conversations match.</${EmptyState}>`:visible.map(c=>html`<${Row} c=${c} selected=${selected} pick=${setSelected}/>` )}</div></aside><main class="e-main"><header class="e-conv-head"><div class="e-breadcrumb">${selected.org} › ${selected.agent} · ${selected.repo} · ${selected.branch}</div><div class="e-title-row"><div class="e-title"><h1>${selected.title}</h1><${StatusPill} status=${selected.status}/></div><div class="e-conv-menu"><button aria-label="Conversation actions" onClick=${()=>setMenu(menu?'': 'actions')}>⋯</button>${menu&&html`<${Menu} open=${true}><button>Open in Orca</button><button>Steer</button><button>Interrupt</button><button>Abort</button></${Menu}>`}</div></div></header><${Thread} c=${selected}/></main><${Details} c=${selected}/>`}
